const output = $input.item.json.stdout || '';
const stderr = $input.item.json.stderr || '';

// Extrai métricas do output
const totalMatch = output.match(/Notas encontradas: (\d+)/);
const brokenMatch = output.match(/Wikilinks quebrados: (\d+)/);
const orphansMatch = output.match(/Notas órfãs em 08-Raw: (\d+)/);

const total = totalMatch ? parseInt(totalMatch[1]) : 0;
const broken = brokenMatch ? parseInt(brokenMatch[1]) : 0;
const orphans = orphansMatch ? parseInt(orphansMatch[1]) : 0;

const status = (broken === 0 && orphans === 0) ? 'OK' : 'ATENÇÃO';

const summary = [
  `*Vault Librarian — ${new Date().toLocaleDateString('pt-BR')}*`,
  `Status: ${status}`,
  `Notas: ${total}`,
  `Links quebrados: ${broken}`,
  `Órfãs em Raw: ${orphans}`,
  broken > 0 || orphans > 0 ? '\nVer relatório: `01-Dashboard/Relatorio-Manutencao.md`' : ''
].filter(Boolean).join('\n');

return [{ json: { summary, total, broken, orphans, status, raw_output: output } }];
